'use strict';
/**
 * Executes the REAL page-side scripts generated by cdp-dom.js inside a vm sandbox with a
 * minimal DOM stub. This verifies the logic that matters for safety (secret redaction,
 * locator behaviour, occlusion detection, invalid selectors) — but a stub is not a browser:
 * layout/CSS/event semantics still need real-Chrome testing.
 */
const test = require('node:test');
const assert = require('node:assert/strict');
const vm = require('node:vm');
const { CdpDom } = require('../src/browser/cdp-dom');

function el(tag, attrs = {}, { text = '', value, rect = { x: 0, y: 0, width: 100, height: 20 }, visible = true, disabled = false } = {}) {
  return {
    tagName: tag.toUpperCase(), id: attrs.id ?? '', innerText: text, value, disabled, _visible: visible, _rect: rect,
    getAttribute: (n) => (n in attrs ? attrs[n] : null),
    getBoundingClientRect: () => ({ ...rect, x: rect.x, y: rect.y }),
    contains: (o) => o === undefined, scrollIntoView() {},
  };
}
function runner(elements, { topAtPoint } = {}) {
  const ctx = {
    document: { querySelectorAll: (sel) => { if (sel === '[') throw new Error('bad'); return elements.filter((e) => sel === '*' || sel.split(',').some((s) => s.trim().replace(/^#/, '') === e.id || s.trim().toLowerCase() === e.tagName.toLowerCase() || (s.startsWith('[name=') && e.getAttribute('name') === s.slice(7, -1).replace(/"/g, '')) || (s.startsWith('input[type=') && e.tagName === 'INPUT' && e.getAttribute('type') === s.slice(11, -1)))); },
      elementFromPoint: () => topAtPoint ?? null, title: 'T', body: { innerText: 'body text' }, forms: [], getElementsByTagName: () => [1, 2, 3] },
    getComputedStyle: (e) => ({ visibility: e._visible ? 'visible' : 'hidden', display: 'block' }),
    CSS: { escape: (s) => s }, location: { href: 'https://a.test/' }, JSON, Math, Event: class {}, scrollX: 0, scrollY: 0, scrollBy() {},
  };
  vm.createContext(ctx);
  const page = { conn: { send: async () => ({}) }, evaluate: async (expression) => vm.runInContext(expression, ctx) };
  return new CdpDom(page);
}

test('password, cc-* and one-time-code values are redacted in query results', async () => {
  const dom = runner([
    el('input', { type: 'password', id: 'pw' }, { value: 'hunter2' }),
    el('input', { type: 'text', autocomplete: 'cc-number', id: 'cc' }, { value: '4111111111111111' }),
    el('input', { type: 'text', autocomplete: 'one-time-code', id: 'otp' }, { value: '123456' }),
    el('input', { type: 'text', id: 'plain' }, { value: 'visible-value' }),
  ]);
  const values = {};
  for (const id of ['pw', 'cc', 'otp', 'plain']) values[id] = (await dom.query({ selector: `#${id}` })).items[0].value;
  assert.deepEqual(values, { pw: '[redacted]', cc: '[redacted]', otp: '[redacted]', plain: 'visible-value' });
});

test('getText and getAttribute(value) never return secret field contents', async () => {
  const dom = runner([el('input', { type: 'password', id: 'pw' }, { value: 'hunter2', text: 'hunter2' })]);
  assert.equal((await dom.getText({ selector: '#pw' })).text, '[redacted]');
  assert.equal((await dom.getAttribute({ selector: '#pw' }, 'value')).value, '[redacted]');
});

test('text locator prefers exact matches over substring matches', async () => {
  const dom = runner([el('button', { id: 'a' }, { text: 'Sign in with Google' }), el('button', { id: 'b' }, { text: 'Sign in' })]);
  const r = await dom.query({ text: 'sign in' });
  assert.equal(r.items[0].id, 'b');
});

test('an invalid selector surfaces as a clear error, not a silent miss', async () => {
  const dom = runner([el('a', { id: 'x' })]);
  await assert.rejects(dom.query({ selector: '[' }), /Invalid selector/);
});

test('click refuses hidden, disabled and missing elements without dispatching input', async () => {
  const sent = [];
  const mk = (elements, opts) => { const d = runner(elements, opts); d.conn = { send: async (m) => { sent.push(m); return {}; } }; return d; };
  await assert.rejects(mk([el('button', { id: 'h' }, { visible: false })]).click({ selector: '#h' }), /not_visible/);
  await assert.rejects(mk([el('button', { id: 'd' }, { disabled: true })]).click({ selector: '#d' }), /disabled/);
  await assert.rejects(mk([]).click({ selector: '#none' }), /not_found/);
  assert.equal(sent.length, 0);
});

test('click detects an element covered by an unrelated element', async () => {
  const overlay = el('div', { id: 'overlay' });
  overlay.contains = () => false;
  const target = el('button', { id: 'go' });
  target.contains = (o) => o === target;
  const sent = [];
  const dom = runner([target], { topAtPoint: overlay });
  dom.conn = { send: async (m, p) => { sent.push(m); return {}; } };
  await assert.rejects(dom.click({ selector: '#go' }), /covered by <div>/);
  assert.equal(sent.length, 0);
});

test('selector text containing quotes/backticks cannot break out of the page script', async () => {
  const dom = runner([el('a', { id: 'x' }, { text: 'hi' })]);
  const evil = `"; throw new Error('pwned'); //\``;
  const r = await dom.query({ text: evil }); // must evaluate as a plain string literal
  assert.equal(r.count, 0);
});
